/**
 * An open workspace database.
 */
public protocol CoreWorkspaceProtocol: AnyObject, Sendable {
    
    /**
     * Forgets the outbox entries the server has accepted.
     */
    func acknowledgeSyncChanges(throughSeq: Int64) throws 
    
    /**
     * Queues a task in a focus session.
     */
    func addToFocusQueue(sessionId: String, taskId: String, plannedSeconds: Int64?, nowMs: Int64) throws 
    
    /**
     * Copies a task's planning onto its subtasks as one step.
     */
    func applyPlanningToDescendants(taskId: String, nowMs: Int64, zone: String) throws 
    
    /**
     * Writes a pull into the workspace; whether anything changed.
     */
    func applyRemoteRows(rows: [IncomingRow], cursor: Int64, hlc: String?, nowMs: Int64) throws  -> Bool
    
    /**
     * Archives a task's daily as one "Archive Daily" step.
     */
    func archiveDaily(taskId: String, nowMs: Int64) throws 
    
    /**
     * Ranks tasks in Today's focus order as one "Reorder Today" step.
     */
    func arrangeDay(orderedTaskIds: [String], nowMs: Int64) throws 
    
    /**
     * Pairs the store with a sync server.
     */
    func beginSync(deviceId: String, serverUrl: String) throws 
    
    /**
     * The workspace, made on first launch with its Inbox and conditions;
     * returns its id.
     */
    func bootstrap(nowMs: Int64) throws  -> String
    
    /**
     * Banks a running block's time.
     */
    func checkpointFocusSession(id: String, nowMs: Int64) throws 
    
    /**
     * Un-ticks a day of a daily as one "Clear Daily" step.
     */
    func clearContribution(dailyId: String, dayMs: Int64, zone: String) throws 
    
    /**
     * Clears the focus order as one "Clear Focus Order" step.
     */
    func clearFocusOrder(nowMs: Int64) throws 
    
    /**
     * Turns a standalone list into a task in the Inbox; returns the task's id.
     */
    func convertListToTask(id: String, nowMs: Int64) throws  -> String
    
    /**
     * Creates a condition as one "New Condition" step; returns its id.
     */
    func createCondition(workspaceId: String, name: String, isLocation: Bool, nowMs: Int64) throws  -> String
    
    /**
     * Creates a folder as one "New Folder" step.
     */
    func createFolder(workspaceId: String, name: String, parentFolderId: String?, nowMs: Int64) throws  -> CreatedItem
    
    /**
     * Creates a list as one "New List" step.
     */
    func createList(workspaceId: String, name: String, folderId: String?, nowMs: Int64) throws  -> CreatedItem
    
    /**
     * Creates a task as one "New Task" step and returns its id.
     */
    func createTask(task: NewTask, nowMs: Int64) throws  -> String
    
    /**
     * Deletes a folder as one "Delete Folder" step; its lists move to the top.
     */
    func deleteFolder(id: String) throws 
    
    /**
     * Deletes a list and its tasks as one "Delete List" step.
     */
    func deleteList(id: String) throws  -> DeletedList
    
    /**
     * Deletes a task and its subtree as one "Delete Task" step.
     */
    func deleteTask(id: String) throws  -> DeletedTask
    
    /**
     * Removes a theme; whether there was one.
     */
    func deleteTheme(id: String) throws  -> Bool
    
    /**
     * A task's editable state, as the editor opens it.
     */
    func editorSnapshot(taskId: String) throws  -> EditorSnapshot
    
    /**
     * Unpairs: stops recording and forgets what was waiting to be sent.
     */
    func endSync() throws 
    
    /**
     * Queues every existing row for the first push after pairing.
     */
    func enqueueSyncSnapshot(nowMs: Int64) throws 
    
    /**
     * Finishes the block in hand as one step: "Complete Task", or "Log Daily
     * Progress" when the task stays open.
     */
    func finishFocusBlock(sessionId: String, elapsedSeconds: Int64, qualityMultiplier: Double?, completeTask: Bool, expectedBlockId: String?, context: FocusContext, nowMs: Int64, zone: String) throws  -> BlockFinished
    
    /**
     * Ends a focus session.
     */
    func finishFocusSession(id: String, nowMs: Int64) throws 
    
    /**
     * Whether a session waiting on a blocked queue can resume in `context`.
     */
    func hasResumableFocusQueueTask(context: FocusContext, nowMs: Int64, zone: String) throws  -> Bool
    
    /**
     * The task and list the next undo (`for_undo`) or redo affects.
     */
    func historyTarget(forUndo: Bool) throws  -> HistoryTarget
    
    /**
     * Brings the plugin-era dailies in once; how many it made.
     */
    func importLegacyDailies(legacy: [LegacyDailySeed], progressTaskIds: [String], nowMs: Int64) throws  -> UInt32
    
    /**
     * Copies tasks from an outside service into the workspace, safely re-run,
     * outside the undo journal.
     */
    func importTasks(workspaceId: String, listName: String, sourceSystem: String, seeds: [ImportedTaskSeed], nowMs: Int64) throws  -> ImportOutcome?
    
    /**
     * Indents a task under the sibling above as one "Indent Task" step.
     */
    func indentTask(id: String, nowMs: Int64) throws 
    
    /**
     * Seeds the saved boards from the old preferences and the defaults;
     * returns every board.
     */
    func kanbanBoardBaseline(legacy: [BoardBaseline], currentKey: String) throws  -> [BoardBaseline]
    
    /**
     * The newest outbox entry, or nothing when nothing is waiting.
     */
    func latestSyncOutboxSeq() throws  -> Int64?
    
    /**
     * Logs progress on a daily as one "Log Daily" step; returns the
     * contribution's id.
     */
    func logContribution(dailyId: String, seconds: Int64, complete: Bool, nowMs: Int64, zone: String) throws  -> String
    
    /**
     * Makes a task a daily as one "Make Daily" step; returns the daily's id.
     */
    func makeDaily(taskId: String, weekdays: [UInt32], intervalDays: Int64?, targetSeconds: Int64?, nowMs: Int64) throws  -> String
    
    /**
