/**
 * What went wrong in the core, as a client sees it.
 *
 * The field is `detail` rather than `message`: Kotlin's generated exception
 * would otherwise clash with `Throwable.message`.
 */
public 
enum CoreError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case Database(detail: String
    )
    case ForeignKeys(identifier: String, count: UInt32
    )
    case NoJournal
    case MissingTask(id: String
    )
    case MissingDaily(id: String
    )
    case MissingList(id: String
    )
    case MissingFolder(id: String
    )
    case SystemListIsPermanent
    case EmptyName
    case InvalidFolderMove
    case InvalidCondition
    case InvalidStatus(status: String
    )
    case InvalidSchedule
    case InvalidMinimum
    case EstimateRequired
    case InvalidDate
    case EditorConflict
    case InvalidVisibleRoot
    case DuplicateSourceId
    case NoActiveFocusTask
    case Unavailable
    case InvalidTaskMove

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension CoreError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCoreError: FfiConverterRustBuffer {
    typealias SwiftType = CoreError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CoreError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Database(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 2: return .ForeignKeys(
            identifier: try FfiConverterString.read(from: &buf), 
            count: try FfiConverterUInt32.read(from: &buf)
            )
        case 3: return .NoJournal
        case 4: return .MissingTask(
            id: try FfiConverterString.read(from: &buf)
            )
        case 5: return .MissingDaily(
            id: try FfiConverterString.read(from: &buf)
            )
        case 6: return .MissingList(
            id: try FfiConverterString.read(from: &buf)
            )
        case 7: return .MissingFolder(
            id: try FfiConverterString.read(from: &buf)
            )
        case 8: return .SystemListIsPermanent
        case 9: return .EmptyName
        case 10: return .InvalidFolderMove
        case 11: return .InvalidCondition
        case 12: return .InvalidStatus(
            status: try FfiConverterString.read(from: &buf)
            )
        case 13: return .InvalidSchedule
        case 14: return .InvalidMinimum
        case 15: return .EstimateRequired
        case 16: return .InvalidDate
        case 17: return .EditorConflict
        case 18: return .InvalidVisibleRoot
        case 19: return .DuplicateSourceId
        case 20: return .NoActiveFocusTask
        case 21: return .Unavailable
        case 22: return .InvalidTaskMove

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: CoreError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Database(detail):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .ForeignKeys(identifier,count):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(identifier, into: &buf)
            FfiConverterUInt32.write(count, into: &buf)
            
        
        case .NoJournal:
            writeInt(&buf, Int32(3))
        
        
        case let .MissingTask(id):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(id, into: &buf)
            
        
        case let .MissingDaily(id):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(id, into: &buf)
            
        
        case let .MissingList(id):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(id, into: &buf)
            
        
        case let .MissingFolder(id):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(id, into: &buf)
            
        
        case .SystemListIsPermanent:
            writeInt(&buf, Int32(8))
        
        
        case .EmptyName:
            writeInt(&buf, Int32(9))
        
        
        case .InvalidFolderMove:
            writeInt(&buf, Int32(10))
        
        
        case .InvalidCondition:
